I'm confident in the chain: geo's pod is crash-looping, search fails on every geo call, and the frontend's /hotels requests return 500. Rate and profile shrink only because search stopped sending them traffic.

```json
{
  "root_causes": [
    {
      "service": "geo",
      "fault_kind": "pod_failure",
      "evidence": [
        {"kind": "metric", "sql": "SELECT metric, attr_k8s_pod_name, count(*) n, min(time) t0, max(time) t1, round(avg(value),3) avg_v, round(max(value),3) max_v FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'geo-%' AND metric IN ('k8s.container.restarts','k8s.container.ready','k8s.pod.phase') GROUP BY ALL ORDER BY 1", "claim": "geo pod restarts climb to 6 (avg 5.2) and it is never ready during the abnormal window; normal period has no restarts"},
        {"kind": "trace", "sql": "SELECT service_name, attr_span_kind, span_name, count(*) n FROM abnormal_traces WHERE service_name = 'geo' GROUP BY ALL UNION ALL SELECT service_name, attr_span_kind, span_name, count(*) FROM normal_traces WHERE service_name = 'geo' GROUP BY ALL", "claim": "geo emits about 1,479 Server spans in the normal period and none in the abnormal period"},
        {"kind": "log", "sql": "SELECT service_name, level, message, count(*) n, min(time) t0, max(time) t1 FROM abnormal_logs WHERE level='ERROR' GROUP BY ALL ORDER BY n DESC", "claim": "search logs 1,234 'Failed to get nearby hotels from geo service' errors over the same window"}
      ]
    }
  ],
  "propagation": [
    {
      "from": "geo",
      "to": "search",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, attr_span_kind, span_name, attr_status_code, count(*) n FROM abnormal_traces WHERE service_name = 'search' GROUP BY ALL", "claim": "search server spans all fail with error status once geo stops answering; search-to-geo calls disappear"}
      ]
    },
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_status_code, attr_http_response_status_code, count(*) n FROM abnormal_traces WHERE service_name = 'frontend' AND attr_span_kind = 'Server' AND span_name = 'HTTP /hotels' GROUP BY ALL", "claim": "frontend /hotels requests return HTTP 500 with Error status, 755 times in the abnormal window"}
      ]
    }
  ]
}
```

